# Case-insensitive lookup index (built once at import)
_LOWER_DICT: dict[str, str] = {k.lower(): v for k, v in KEYWORD_DICT.items()}


def translate_keywords(keywords: list[str]) -> list[str]:
    """Translate a list of EN keywords to FR using the dictionary.
    Falls back to original keyword if not found."""
    result = []
    for kw in keywords:
        kw_stripped = kw.strip()
        # Try exact match first, then case-insensitive
        if kw_stripped in KEYWORD_DICT:
            result.append(KEYWORD_DICT[kw_stripped])
        elif kw_stripped.lower() in _LOWER_DICT:
            result.append(_LOWER_DICT[kw_stripped.lower()])
        else:
            result.append(kw_stripped)
    return result


def get_coverage(keywords: list[str]) -> float:
    """Return the fraction of keywords that exist in the dictionary (0.0 to 1.0)."""
    if not keywords:
        return 1.0
    found = sum(1 for kw in keywords if kw.strip().lower() in _LOWER_DICT)
    return found / len(keywords)
